    %% font id without checking it. Machines with no TrueType
    %% font at all skip the calls that take one.
    fnt = -1;
    fontFile = PsychNanoVGFonts('FindSystemFont', 'Arial');
    if isempty(fontFile)
        fontFile = PsychNanoVGFonts('FindSystemFont', 'DejaVuSans');
    end
    if ~isempty(fontFile)
        fnt = PsychNanoVG('CreateFont', 'sans', fontFile);
    end
    tst('ok', 'gen CreateFont', fnt >= 0 || isempty(fontFile));

    % value = PsychNanoVG('AddFallbackFont', baseFont, fallbackFont)
    tcall('AddFallbackFont', {'abc', 'abc'}, {[1, 1]});
    % value = PsychNanoVG('AddFallbackFontId', baseFont, fallbackFont)
    if fnt >= 0, tcall('AddFallbackFontId', {fnt, fnt}, {[1, 1]}); end
    % PsychNanoVG('Arc', cx, cy, r, a0, a1, dir)
    tcall('Arc', {1, 1, 1, 1, 1, 1}, {});
    % PsychNanoVG('ArcTo', x1, y1, x2, y2, radius)
    tcall('ArcTo', {1, 1, 1, 1, 1}, {});
    % PsychNanoVG('BeginPath')
    tcall('BeginPath', {}, {});
    % PsychNanoVG('BezierTo', c1x, c1y, c2x, c2y, x, y)
    tcall('BezierTo', {1, 1, 1, 1, 1, 1}, {});
    % paint = PsychNanoVG('BoxGradient', x, y, w, h, r, f, icol, ocol)
    tcall('BoxGradient', {1, 1, 1, 1, 1, 1, [1 0.5 0.25 1], [1 0.5 0.25 1]}, {[1, 1]});
    % PsychNanoVG('Circle', cx, cy, r)
    tcall('Circle', {1, 1, 1}, {});
    % PsychNanoVG('ClosePath')
    tcall('ClosePath', {}, {});
    % CreateFont takes a file path; covered by tests/gl.
    % CreateFontAtIndex takes a file path; covered by tests/gl.
    % value = PsychNanoVG('CreateFontMem', name, data)
    tcall('CreateFontMem', {'abc', uint8(1:32)}, {[1, 1]});
    % value = PsychNanoVG('CreateFontMemAtIndex', name, data, fontIndex)
    tcall('CreateFontMemAtIndex', {'abc', uint8(1:32), 0}, {[1, 1]});
    % CreateImage takes a file path; covered by tests/gl.
    % CreateImageMem is covered by test_dispatch, not here.
    % value = PsychNanoVG('CreateImageRGBA', imageFlags, data)
    tcall('CreateImageRGBA', {0, zeros(8, 8, 4, 'uint8')}, {[1, 1]});
    % xform = PsychNanoVG('CurrentTransform')
    tcall('CurrentTransform', {}, {[1, 6]});
    % value = PsychNanoVG('DegToRad', deg)
    tcall('DegToRad', {1}, {[1, 1]});
    % DeleteImage is covered by test_dispatch, not here.
