function tcall(name, args, want)
%   want{k} is [rows cols] for output k, or [] for any size.
    global TST_PASS TST_FAIL %#ok<GVMIS>
    try
        if isempty(want)
            PsychNanoVG(name, args{:});
            good = true;
        else
            outs = cell(1, numel(want));
            [outs{:}] = PsychNanoVG(name, args{:});
            good = true;
            for k = 1:numel(want)
                w = want{k};
                if isempty(w); continue; end
                if ~isequal(size(outs{k}), w); good = false; end
            end
        end
        if good
            TST_PASS = TST_PASS + 1;
        else
            TST_FAIL = TST_FAIL + 1;
            fprintf(2, '  FAIL  gen %s output size\n', name);
        end
    catch e
        TST_FAIL = TST_FAIL + 1;
        fprintf(2, '  FAIL  gen %s: %s\n', name, e.message);
    end
end
